(1054, 'Taman Kyai Langgeng - Tempat Wisata Magelang', 'https://www.google.com/maps/search/?api=1&query=Taman%20Kyai%20Langgeng%20-%20Tempat%20Wisata%20Magelang&query_place_id=ChIJ0UZPZl2Pei4Rg_Fgft8rRsM', 3, 'Jesica Dinna', 'https://www.google.com/maps/reviews/data=!4m8!14m7!1m6!2m5!1sChdDSUhNMG9nS0VJQ0FnSURRb0pXczJBRRAB!2m1!1s0x0:0xc3462bdf7e60f183!3m1!1s2@1:CIHM0ogKEICAgIDQoJWs2AE%7C%7C?hl=id', 'Tempat berkumpul bersama keluarga yang asri, lumayan bersih, bisa melihat satwa, untuk ber swafoto', 'positif', 2.00, '2026-06-01 15:04:03'),
(1055, 'Taman Kyai Langgeng - Tempat Wisata Magelang', 'https://www.google.com/maps/search/?api=1&query=Taman%20Kyai%20Langgeng%20-%20Tempat%20Wisata%20Magelang&query_place_id=ChIJ0UZPZl2Pei4Rg_Fgft8rRsM', 5, 'Nurul Nitasari', 'https://www.google.com/maps/reviews/data=!4m8!14m7!1m6!2m5!1sChdDSUhNMG9nS0VJQ0FnSUN1LV9tbmdnRRAB!2m1!1s0x0:0xc3462bdf7e60f183!3m1!1s2@1:CIHM0ogKEICAgICu-_mnggE%7C%7C?hl=id', 'Murah, wahana lengkap, parkir luas, family friendly', 'netral', 0.00, '2026-06-01 15:04:03'),
(1056, 'Taman Kyai Langgeng - Tempat Wisata Magelang', 'https://www.google.com/maps/search/?api=1&query=Taman%20Kyai%20Langgeng%20-%20Tempat%20Wisata%20Magelang&query_place_id=ChIJ0UZPZl2Pei4Rg_Fgft8rRsM', 5, 'petugas puskesmas', 'https://www.google.com/maps/reviews/data=!4m8!14m7!1m6!2m5!1sChdDSUhNMG9nS0VJQ0FnSUNBOU1hWnZ3RRAB!2m1!1s0x0:0xc3462bdf7e60f183!3m1!1s2@1:CIHM0ogKEICAgICA9MaZvwE%7C%7C?hl=id', 'Tempat rekreasi yang nyaman,sejuk,mengasyikan banget buat keluarga', 'netral', 0.00, '2026-06-01 15:04:03'),
