(1215, 'Taman Kyai Langgeng - Tempat Wisata Magelang', 'https://www.google.com/maps/search/?api=1&query=Taman%20Kyai%20Langgeng%20-%20Tempat%20Wisata%20Magelang&query_place_id=ChIJ0UZPZl2Pei4Rg_Fgft8rRsM', 5, 'Akhid Fandy', 'https://www.google.com/maps/reviews/data=!4m8!14m7!1m6!2m5!1sCi9DQUlRQUNvZENodHljRjlvT2s1V1ZsSlZlR3QzYzNaMVQyWk9hMkUyV2pFdGVuYxAB!2m1!1s0x0:0xc3462bdf7e60f183!3m1!1s2@1:CAIQACodChtycF9oOk5WVlJVeGt3c3Z1T2ZOa2E2WjEtenc%7C%7C?hl=id', 'Banyak wahana yang menarik untuk dicoba', 'positif', 1.00, '2026-06-01 15:04:03'),
(1216, 'Taman Kyai Langgeng - Tempat Wisata Magelang', 'https://www.google.com/maps/search/?api=1&query=Taman%20Kyai%20Langgeng%20-%20Tempat%20Wisata%20Magelang&query_place_id=ChIJ0UZPZl2Pei4Rg_Fgft8rRsM', 5, 'Wahyu Ananto', 'https://www.google.com/maps/reviews/data=!4m8!14m7!1m6!2m5!1sChdDSUhNMG9nS0VJQ0FnSUNnbXBIM29nRRAB!2m1!1s0x0:0xc3462bdf7e60f183!3m1!1s2@1:CIHM0ogKEICAgICgmpH3ogE%7C%7C?hl=id', 'Asyiiiik tenan.tiket30rb bs mnaiki wahana ampe 10.didalam MANTAAAB.', 'netral', 0.00, '2026-06-01 15:04:03'),
